class Ship {
  constructor(name) { this.name = name; this.fuel = 100; }
  fly(km) {
    this.fuel -= km / 10;
  }
  get isEmpty() {
    return this.fuel <= 0;
  }
}
const s = new Ship("Kartal");
s.fly(300);
console.log(s.fuel, s.isEmpty);

